export function initConfirmedOverview(){
 const target=document.querySelector('#confirmed-overview');if(!target)return{refresh(){}};const period=document.querySelector('#overview-period'),status=target.querySelector('[role=status]'),grid=target.querySelector('.metrics-grid');let generation=0;
 const fields={pessoas_apoiadas:['Pessoas apoiadas','Identidades do CRM com apoio realizado, contadas uma vez no mês.'],familias_apoiadas:['Famílias apoiadas','Famílias vinculadas ao apoio realizado, contadas uma vez no mês.'],atividades_realizadas:['Apoios realizados','Atividades e entregas confirmadas no CRM e na agenda, sem repetir eventos vinculados.'],cestas_entregues:['Cestas entregues','Quantidades confirmadas em serviços classificados como cesta básica.'],pecas_entregues:['Peças entregues','Quantidade confirmada nos serviços medidos em peças. Não representa número de pessoas.'],itens_entregues:['Itens entregues','Quantidade confirmada de itens e utensílios. Não representa número de pessoas.']};
 async function refresh(){const current=++generation;try{const response=await fetch('/api/crm/impacto?periodo='+encodeURIComponent(period.value),{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível consultar.');if(current!==generation)return;if([...Object.keys(fields),'cadastros_sem_identidade'].some(key=>!Number.isSafeInteger(data[key])||data[key]<0))throw Error('Resposta incompleta.');grid.replaceChildren();for(const[key,[title,hint]]of Object.entries(fields)){const card=document.createElement('article');card.className='metric-card';for(const[tag,text]of [['span',title],['strong',new Intl.NumberFormat('pt-BR').format(data[key])],['small',hint]]){const el=document.createElement(tag);el.textContent=text;card.append(el);}grid.append(card);}status.textContent='Apoios confirmados no CRM e na agenda. '+(data.cadastros_sem_identidade ? data.cadastros_sem_identidade+' cadastro(s) com apoio realizado aguardam identificação no CRM e não entram no total de pessoas.' : 'Todos os cadastros com apoio neste período possuem identificação no CRM.')+' Os totais históricos não são somados a este quadro.';}catch(error){if(current===generation){grid.replaceChildren();status.textContent='Não foi possível consultar a execução confirmada. '+error.message;}}}
 return{refresh};
}
